import { precacheAndRoute, cleanupOutdatedCaches } from 'workbox-precaching';
import { registerRoute, NavigationRoute } from 'workbox-routing';
import { NetworkOnly, CacheFirst } from 'workbox-strategies';
import { ExpirationPlugin } from 'workbox-expiration';
import { CacheableResponsePlugin } from 'workbox-cacheable-response';

// Clean up old caches
cleanupOutdatedCaches();

// Precache all assets generated by Vite build (including offline.html, JS, CSS, icons)
precacheAndRoute(self.__WB_MANIFEST || []);

// 1. Strictly exclude /admin and /api from caching (always network only)
registerRoute(
  ({ url }) => url.pathname.startsWith('/admin') || url.pathname.startsWith('/api'),
  new NetworkOnly()
);

// 2. Cache Cloudinary images (CacheFirst)
registerRoute(
  ({ url }) => url.origin === 'https://res.cloudinary.com',
  new CacheFirst({
    cacheName: 'cloudinary-images',
    plugins: [
      new ExpirationPlugin({
        maxEntries: 60,
        maxAgeSeconds: 30 * 24 * 60 * 60, // 30 days
      }),
      new CacheableResponsePlugin({
        statuses: [0, 200],
      }),
    ],
  })
);

// 3. Cache Google Fonts
registerRoute(
  ({ url }) => url.origin.includes('fonts.googleapis.com') || url.origin.includes('fonts.gstatic.com'),
  new CacheFirst({
    cacheName: 'google-fonts',
    plugins: [
      new ExpirationPlugin({
        maxEntries: 20,
        maxAgeSeconds: 365 * 24 * 60 * 60, // 1 year
      }),
      new CacheableResponsePlugin({
        statuses: [0, 200],
      }),
    ],
  })
);

// 4. Navigation requests handling:
// Attempt network fetch first. If offline / network fails, serve the precached /offline.html fallback.
// Strictly denylist /admin and /api so admin routes are never served from offline cache.
const navigationHandler = async ({ request }) => {
  try {
    const response = await fetch(request);
    return response;
  } catch (error) {
    const offlineFallback = await caches.match('/offline.html');
    if (offlineFallback) {
      return offlineFallback;
    }
    return Response.error();
  }
};

const navigationRoute = new NavigationRoute(navigationHandler, {
  denylist: [/^\/admin/, /^\/api/],
});

registerRoute(navigationRoute);

self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') {
    self.skipWaiting();
  }
});
